import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Getting Started with TermBolt","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function r(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started-with-termbolt" tabindex="-1">Getting Started with TermBolt <a class="header-anchor" href="#getting-started-with-termbolt" aria-label="Permalink to &quot;Getting Started with TermBolt&quot;">​</a></h1><p>Welcome to <strong>TermBolt</strong>, an ultra-fast, modern remote access client designed for system administrators, DevOps engineers, and developers managing fleets of remote servers and local workstations.</p><hr><h2 id="📥-installation" tabindex="-1">📥 Installation <a class="header-anchor" href="#📥-installation" aria-label="Permalink to &quot;📥 Installation&quot;">​</a></h2><h3 id="🪟-windows-setup-wizard" tabindex="-1">🪟 Windows (Setup Wizard) <a class="header-anchor" href="#🪟-windows-setup-wizard" aria-label="Permalink to &quot;🪟 Windows (Setup Wizard)&quot;">​</a></h3><ol><li>Download <strong><code>TermBolt-Setup.exe</code></strong> from the <a href="https://github.com/stahiralijan/termbolt-releases/releases/latest" target="_blank" rel="noreferrer">Official Releases</a>.</li><li>Run the installer wizard. TermBolt will install seamlessly to <code>C:\\Program Files\\TermBolt</code> (or <code>%LOCALAPPDATA%\\Programs\\TermBolt</code>) with desktop and start menu shortcuts.</li><li>Launch <strong>TermBolt</strong> from your desktop or start menu.</li></ol><h3 id="🍎-macos-apple-silicon-intel" tabindex="-1">🍎 macOS (Apple Silicon &amp; Intel) <a class="header-anchor" href="#🍎-macos-apple-silicon-intel" aria-label="Permalink to &quot;🍎 macOS (Apple Silicon &amp; Intel)&quot;">​</a></h3><ol><li>Download <strong><code>TermBolt-mac-arm64.dmg</code></strong> (Apple Silicon) or <strong><code>TermBolt-mac-x64.dmg</code></strong> (Intel).</li><li>Open the <code>.dmg</code> file and drag <strong>TermBolt</strong> into your <code>/Applications</code> folder.</li><li>Launch TermBolt from Launchpad or Spotlight.</li></ol><h3 id="🐧-linux-appimage-debian-package" tabindex="-1">🐧 Linux (AppImage &amp; Debian Package) <a class="header-anchor" href="#🐧-linux-appimage-debian-package" aria-label="Permalink to &quot;🐧 Linux (AppImage &amp; Debian Package)&quot;">​</a></h3><ol><li><strong>AppImage</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TermBolt-linux-x64.AppImage</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./TermBolt-linux-x64.AppImage</span></span></code></pre></div></li><li><strong>Debian / Ubuntu (<code>.deb</code>)</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TermBolt-linux-amd64.deb</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # resolve any missing dependencies</span></span></code></pre></div></li></ol><h3 id="🤖-android-companion-client" tabindex="-1">🤖 Android Companion Client <a class="header-anchor" href="#🤖-android-companion-client" aria-label="Permalink to &quot;🤖 Android Companion Client&quot;">​</a></h3><ol><li>Download <strong><code>TermBolt-android-arm64.apk</code></strong> to your Android device (Android 9.0+).</li><li>Allow installation from unknown sources in settings if prompted.</li><li>Open the APK to install the TermBolt mobile client.</li></ol><hr><h2 id="🚀-quick-tour" tabindex="-1">🚀 Quick Tour <a class="header-anchor" href="#🚀-quick-tour" aria-label="Permalink to &quot;🚀 Quick Tour&quot;">​</a></h2><h3 id="_1-connecting-to-a-server" tabindex="-1">1. Connecting to a Server <a class="header-anchor" href="#_1-connecting-to-a-server" aria-label="Permalink to &quot;1. Connecting to a Server&quot;">​</a></h3><ul><li>Click the <strong><code>+</code></strong> button in the Host sidebar to add a new server profile.</li><li>Configure connection parameters: <strong>Protocol</strong> (<code>SSH</code>, <code>Telnet</code>, <code>Local Shell</code>, <code>VNC</code>), <strong>Address / IP</strong>, <strong>Port</strong> (default 22), and <strong>Credentials</strong>.</li><li>Double-click the host card to open a new tab session.</li></ul><h3 id="_2-fast-navigation-via-command-launcher-ctrl-k" tabindex="-1">2. Fast Navigation via Command Launcher (<code>Ctrl+K</code>) <a class="header-anchor" href="#_2-fast-navigation-via-command-launcher-ctrl-k" aria-label="Permalink to &quot;2. Fast Navigation via Command Launcher (`Ctrl+K`)&quot;">​</a></h3><p>Press <kbd>Ctrl</kbd> + <kbd>K</kbd> from anywhere in the application to open the <strong>Fuzzy Quick-Connect Launcher</strong>. Type any keyword, server name, or IP to jump directly into the session.</p><h3 id="_3-in-terminal-search-ctrl-f" tabindex="-1">3. In-Terminal Search (<code>Ctrl+F</code>) <a class="header-anchor" href="#_3-in-terminal-search-ctrl-f" aria-label="Permalink to &quot;3. In-Terminal Search (`Ctrl+F`)&quot;">​</a></h3><p>Search your active scrollback buffer instantly by pressing <kbd>Ctrl</kbd> + <kbd>F</kbd>. Match navigation with <kbd>Enter</kbd> (next) and <kbd>Shift+Enter</kbd> (previous).</p><hr><h2 id="🔒-master-vault-unlock" tabindex="-1">🔒 Master Vault Unlock <a class="header-anchor" href="#🔒-master-vault-unlock" aria-label="Permalink to &quot;🔒 Master Vault Unlock&quot;">​</a></h2><p>On first launch, you will be prompted to set an optional <strong>Master Password</strong> to lock your local credential vault.</p><ul><li>All stored credentials (passwords, private keys, passphrases) are encrypted using <strong>AES-256-GCM</strong> with a <strong>PBKDF2 SHA-256 (100,000 rounds)</strong> derived key.</li><li>If locked, click the lock icon in the top titlebar or press <kbd>Ctrl</kbd> + <kbd>,</kbd> to enter your master key.</li></ul>',24)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
